type Ctor = new (...args: any[]) => {};

function Comparable<TBase extends Ctor>(Base: TBase) {   // mixin factory
  return class extends Base {
    isGreaterThan(other: unknown) { return (this as any).compare(other) > 0; }
  };
}

interface ComparableTo<T> { compareTo(other: T): number }
function greater<T extends ComparableTo<T>>(a: T, b: T): boolean { return a.compareTo(b) > 0 }
